cd /home/ubuntu/.agent-ml-research-idea_gen_0509_15/projects/vla-ssd/docs/paper && python3 -c "
import subprocess
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\x0c')
# Search for 'References' as a section header across all pages
for i in range(len(pages)-1):
    if 'References' in pages[i]:
        # Check if it's the actual bibliography header (not just a word in text)
        lines = pages[i].split('\n')
        for line in lines:
            if 'References' in line and len(line.strip()) < 30:
                print(f'Page {i+1}: found References header: \"{line.strip()}\"')
    if 'Supplementary Material' in pages[i]:
        print(f'Page {i+1}: Appendix start')
    if '[1]' in pages[i][:300] or '[2]' in pages[i][:300]:
        print(f'Page {i+1}: likely bibliography entries')
"

